  func CreateColorPackageInternal(accents : ColorPackage) : ColorPackage
  {
    return {
      GeneralBackground: cast Color "#2D2D30";
      GeneralBorder: cast Color "#434346";
      GeneralAccent: accents.GeneralAccent;
      ContentBackground: cast Color "#252526";
      ContentBorder: cast Color "#3F3F46";
      Transparent: cast Color "#00000000";
      WindowBorderActive: accents.WindowBorderActive;
      TextSecondary: cast Color "#999999";
      TextDisabled: cast Color "#6D6D6D";
      GroupText: cast Color "#C7C7C7";
      TextNormal: cast Color "#F1F1F1";
      TextBright: cast Color "#FFFFFF";
      ButtonBackgroundHovered: cast Color "#54545C";
      ButtonBorderHovered: cast Color "#6A6A75";
      ControlAccentHovered: accents.ControlAccentHovered;
      ListColumnBorder: cast Color "#404042";
      TabHighlightedSelected: accents.TabHighlightedSelected;
      TabHighlightedHovered: accents.TabHighlightedHovered;
      TabHighlightedBackground: accents.TabHighlightedBackground;
      ScrollBackground: cast Color "#3D3D42";
      ArrowDisabled: cast Color "#555558";
      ArrowAccentHovered: accents.ArrowAccentHovered;
      ScrollHandleHovered: cast Color "#9E9E9E";
      ScrollHandlePressed: cast Color "#EFEBEF";
